	@Test
	void c4CodeTypeRewriteWithoutScopeFlags() {
		Model data = model();
		IRI type = org.eclipse.rdf4j.model.vocabulary.RDF.TYPE;
		data.add(VF.createIRI("urn:t:e1"), type, VF.createIRI("urn:t:T1"));
		add(data, "e1", "code", VF.createLiteral("1.0", CoreDatatype.XSD.DECIMAL));
		data.add(VF.createIRI("urn:t:e2"), type, VF.createIRI("urn:t:T2"));
		add(data, "e2", "code", VF.createLiteral("2", CoreDatatype.XSD.INTEGER));
		String query = """
				SELECT (COUNT(DISTINCT ?e) AS ?n) WHERE {
				  { ?e a :T1 . ?e :code ?c . VALUES ?t { 1 2 } FILTER(?c = ?t || ?c = 3) }
				  UNION
				  { ?e a :T2 . ?e :code ?c . VALUES ?t { 1 2 } FILTER(?c = ?t || ?c = 3) }
				}
				""";
		TupleExpr original = parse(query);
		original.visit(new org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(org.eclipse.rdf4j.query.algebra.QueryModelNode node) {
				if (node instanceof org.eclipse.rdf4j.query.algebra.VariableScopeChange scope
						&& !(node instanceof org.eclipse.rdf4j.query.algebra.Projection)) {
					scope.setVariableScopeChange(false);
				}
				super.meetNode(node);
			}
		});
		List<String> reference = evaluate(data, original);
		PackedQuery packed = PackedQueryCodec.encodeForPlanning(original.clone(), null);
		long generated = 0L;
		for (int relationId = 1; relationId <= packed.relationCount(); relationId++) {
			generated |= packed.relRuleMask(relationId);
		}
		TupleExpr selected = PackedCascadesPlanner
				.optimize(original.clone(), OptimizationGoal.root(original, null), SUBJECT_LOOKUP_COSTS)
				.selectedPlan();
		List<String> actual = evaluate(data, selected);
		System.out.println("[review-codetype] generated=0x" + Long.toHexString(generated) + " reference="
				+ reference + " actual=" + actual + "\n" + original + "\n" + selected);
		assertEquals(reference, actual, "generated=0x" + Long.toHexString(generated) + "\n" + selected);
	}

