	// ------------------------------------------------------------------ harness
	private static void assertPackedPlanPreservesResults(Model data, String query, PackedCostModel costs,
			PackedPredicateRangeProvider provider, List<String> expected) {
		TupleExpr original = parse(query);
		List<String> reference = evaluate(data, original);
		PackedQuery packed = PackedQueryCodec.encodeForPlanning(original.clone(), provider);
		long generated = 0L;
		for (int relationId = 1; relationId <= packed.relationCount(); relationId++) {
			generated |= packed.relRuleMask(relationId);
		}
		TupleExpr selected = PackedCascadesPlanner
				.optimize(original.clone(), OptimizationGoal.root(original, null), costs, provider)
				.selectedPlan();
		List<String> actual = evaluate(data, selected);
		System.out.println("[review] query=" + query + "\n[review] generatedRuleMask=0x"
				+ Long.toHexString(generated) + " reference=" + reference + " actual=" + actual
				+ "\n[review] selected plan:\n" + selected);
		if (expected != null) {
			List<String> sortedExpected = new ArrayList<>(expected);
			Collections.sort(sortedExpected);
			assertEquals(sortedExpected, reference, "reference oracle disagrees with hand-computed bag");
		}
		assertEquals(reference, actual, "selected packed plan changed the result bag (generatedRuleMask=0x"
				+ Long.toHexString(generated) + ")\n" + selected);
	}

	private static TupleExpr parse(String query) {
		return new SPARQLParser().parseQuery(PREFIXES + query, "urn:t:").getTupleExpr();
	}

	private static List<String> evaluate(Model data, TupleExpr expression) {
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
					Value object, Resource... contexts) {
				return new CloseableIteratorIteration<>(data.getStatements(subject, predicate, object, contexts)
						.iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		QueryRoot root = expression instanceof QueryRoot queryRoot ? queryRoot.clone()
				: new QueryRoot(expression.clone());
		List<String> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> result = new StrictEvaluationStrategy(source, null).precompile(root)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				BindingSet bindings = result.next();
				TreeMap<String, String> sorted = new TreeMap<>();
				for (String name : bindings.getBindingNames()) {
					Value value = bindings.getValue(name);
					if (value != null) {
						sorted.put(name, value.toString());
					}
				}
				StringBuilder builder = new StringBuilder();
				sorted.forEach((name, value) -> {
					if (builder.length() > 0) {
						builder.append('|');
					}
					builder.append(name).append('=').append(value);
				});
				rows.add(builder.toString());
			}
		}
		Collections.sort(rows);
		return rows;
	}

	private static Model model() {
		return new LinkedHashModel();
	}

	private static void add(Model model, String subject, String predicate, Value object) {
		model.add(VF.createIRI("urn:t:" + subject), VF.createIRI("urn:t:" + predicate), object);
	}
